//
//   node tests/ven-song-night-probe.mjs --label=dem-B [--dist=<thư mục>] [--dpr=2] [--w=1440] [--h=900] [--query=lightsets=sync]
//        [--cams=doc-song,sat-nuoc,tren-cao] [--parts] [--flicker] [--warm=90]
//   --parts:   tách chi phí trên cùng một trang: pixelRatio 2 / 1,5 / 1, tắt bloom, tắt vệt đèn (vá shader lúc chạy), tắt gương
//   --flicker: đo nhấp nháy vùng nước giữa các khung liên tiếp (độ chói đổi mỗi 1/60 s), lưu 3 ảnh cắt liên tiếp
